// B2CServiceServer is the server API for B2CService service.
// All implementations must embed UnimplementedB2CServiceServer
// for forward compatibility.
//
// B2CService is everything the Auto-Garaj consumer mobile app needs and the shop-management
// side of the product does not have: the public directory of services, the garage a driver
// keeps across shops, bookings made from a phone, reviews, favourites, promos, cashback,
// chats, notifications and roadside help.
//
// It is deliberately self-contained — it calls no other service. Where a record has a real
// counterpart on the B2B side the link is kept as an id (Provider.shop_id,
// Booking.appointment_id) and filled in by the gateway, so the two halves can be joined
// later without this service having to reach across.
//
// Two conventions run through the whole file:
//   - Money is whole so'm, like everywhere else in AvtoMS. Never tiyin.
//   - The caller is a phone number in E.164-ish form ("998901234567"), taken from the
//     client's token by the gateway and never from the request body.
type B2CServiceServer interface {
	// ── Profile and devices ────────────────────────────────────────────────────────────
	// GetProfile returns the app user for a phone, creating the record on first sight — a
	// driver who has just verified an OTP has no profile yet and must not get a 404.
	GetProfile(context.Context, *GetProfileRequest) (*AppUser, error)
	UpdateProfile(context.Context, *UpdateProfileRequest) (*AppUser, error)
	// DeleteProfile erases the account and everything hanging off it. The "delete my account"
	// button in the profile screen is a real promise, so this is a real delete.
	DeleteProfile(context.Context, *DeleteProfileRequest) (*DeleteResponse, error)
	RegisterDevice(context.Context, *RegisterDeviceRequest) (*Device, error)
	DeleteDevice(context.Context, *DeleteDeviceRequest) (*DeleteResponse, error)
	// ── Reference data ─────────────────────────────────────────────────────────────────
	ListCities(context.Context, *ListCitiesRequest) (*ListCitiesResponse, error)
	ListCategories(context.Context, *ListCategoriesRequest) (*ListCategoriesResponse, error)
	// ── Directory ──────────────────────────────────────────────────────────────────────
	ListProviders(context.Context, *ListProvidersRequest) (*ListProvidersResponse, error)
	GetProvider(context.Context, *GetProviderRequest) (*Provider, error)
	ListProviderServices(context.Context, *ListProviderServicesRequest) (*ListProviderServicesResponse, error)
	ListMapPoints(context.Context, *ListMapPointsRequest) (*ListMapPointsResponse, error)
	ListFuelStations(context.Context, *ListFuelStationsRequest) (*ListFuelStationsResponse, error)
	GetFuelStation(context.Context, *GetFuelStationRequest) (*FuelStation, error)
	// Search covers the search screen: providers, matching categories, the caller's recent
	// queries and what everyone else is looking for.
	Search(context.Context, *SearchRequest) (*SearchResponse, error)
	ClearSearchHistory(context.Context, *ClearSearchHistoryRequest) (*DeleteResponse, error)
	// GetHome is the home screen in one call — stories, categories, nearby, promos, the
	// booking in flight and the car that is due an oil change. A phone on a bad connection
	// should not need eight round trips to draw its first screen.
	GetHome(context.Context, *GetHomeRequest) (*HomeResponse, error)
	// ── Reviews and complaints ─────────────────────────────────────────────────────────
	ListReviews(context.Context, *ListReviewsRequest) (*ListReviewsResponse, error)
	CreateReview(context.Context, *CreateReviewRequest) (*Review, error)
	// SetReviewReply is the shop's answer under a review. Written from the B2B side later;
	// it exists now so the mobile app can render replies it will eventually receive.
	SetReviewReply(context.Context, *SetReviewReplyRequest) (*Review, error)
	CreateComplaint(context.Context, *CreateComplaintRequest) (*Complaint, error)
	ListComplaints(context.Context, *ListComplaintsRequest) (*ListComplaintsResponse, error)
	// ── Favourites ─────────────────────────────────────────────────────────────────────
	ListFavorites(context.Context, *ListFavoritesRequest) (*ListFavoritesResponse, error)
	SetFavorite(context.Context, *SetFavoriteRequest) (*SetFavoriteResponse, error)
	// ── The driver's garage ────────────────────────────────────────────────────────────
	ListCars(context.Context, *ListCarsRequest) (*ListCarsResponse, error)
	GetCar(context.Context, *GetCarRequest) (*Car, error)
	CreateCar(context.Context, *CreateCarRequest) (*Car, error)
	UpdateCar(context.Context, *UpdateCarRequest) (*Car, error)
	DeleteCar(context.Context, *DeleteCarRequest) (*DeleteResponse, error)
	SetDefaultCar(context.Context, *SetDefaultCarRequest) (*Car, error)
	// ── Booking ────────────────────────────────────────────────────────────────────────
	ListSlots(context.Context, *ListSlotsRequest) (*ListSlotsResponse, error)
	CreateBooking(context.Context, *CreateBookingRequest) (*Booking, error)
	GetBooking(context.Context, *GetBookingRequest) (*Booking, error)
	ListBookings(context.Context, *ListBookingsRequest) (*ListBookingsResponse, error)
	CancelBooking(context.Context, *CancelBookingRequest) (*Booking, error)
	RescheduleBooking(context.Context, *RescheduleBookingRequest) (*Booking, error)
	// SetBookingState is the shop moving a booking along. Until the B2B side drives it, the
	// gateway's admin route and the demo seed are what call it.
	SetBookingState(context.Context, *SetBookingStateRequest) (*Booking, error)
	// LinkBookingAppointment records the work-order appointment a booking became. Called by
	// the gateway right after it creates that appointment, best-effort: a booking with no
	// appointment is still a booking.
	LinkBookingAppointment(context.Context, *LinkBookingAppointmentRequest) (*Booking, error)
	// ── Cards, promo codes and payment ─────────────────────────────────────────────────
	ListCards(context.Context, *ListCardsRequest) (*ListCardsResponse, error)
	AddCard(context.Context, *AddCardRequest) (*Card, error)
	DeleteCard(context.Context, *DeleteCardRequest) (*DeleteResponse, error)
	SetDefaultCard(context.Context, *SetDefaultCardRequest) (*Card, error)
	ValidatePromoCode(context.Context, *ValidatePromoCodeRequest) (*ValidatePromoCodeResponse, error)
	CreatePayment(context.Context, *CreatePaymentRequest) (*Payment, error)
	GetPayment(context.Context, *GetPaymentRequest) (*Payment, error)
	ListPayments(context.Context, *ListPaymentsRequest) (*ListPaymentsResponse, error)
	// ── Promos and stories ─────────────────────────────────────────────────────────────
	ListPromos(context.Context, *ListPromosRequest) (*ListPromosResponse, error)
	GetPromo(context.Context, *GetPromoRequest) (*Promo, error)
	ListStories(context.Context, *ListStoriesRequest) (*ListStoriesResponse, error)
	MarkStorySeen(context.Context, *MarkStorySeenRequest) (*DeleteResponse, error)
	// ── Cashback ───────────────────────────────────────────────────────────────────────
	GetBonusAccount(context.Context, *GetBonusAccountRequest) (*BonusAccount, error)
	ListBonusEntries(context.Context, *ListBonusEntriesRequest) (*ListBonusEntriesResponse, error)
	// ── Chats and support ──────────────────────────────────────────────────────────────
	ListChats(context.Context, *ListChatsRequest) (*ListChatsResponse, error)
	GetChat(context.Context, *GetChatRequest) (*GetChatResponse, error)
	SendChatMessage(context.Context, *SendChatMessageRequest) (*ChatMessage, error)
	MarkChatRead(context.Context, *MarkChatReadRequest) (*Chat, error)
	// ── Notifications ──────────────────────────────────────────────────────────────────
	ListNotifications(context.Context, *ListNotificationsRequest) (*ListNotificationsResponse, error)
	MarkNotificationRead(context.Context, *MarkNotificationReadRequest) (*Notification, error)
	MarkAllNotificationsRead(context.Context, *MarkAllNotificationsReadRequest) (*DeleteResponse, error)
	// GetBadges is the number on the bell and the number on the chat tab, in one cheap call
	// the app can poll.
	GetBadges(context.Context, *GetBadgesRequest) (*GetBadgesResponse, error)
	// ── Roadside help (SOS) ────────────────────────────────────────────────────────────
	ListEmergencyTypes(context.Context, *ListEmergencyTypesRequest) (*ListEmergencyTypesResponse, error)
	CreateEmergencyRequest(context.Context, *CreateEmergencyRequestRequest) (*EmergencyRequest, error)
	GetEmergencyRequest(context.Context, *GetEmergencyRequestRequest) (*EmergencyRequest, error)
	ListEmergencyRequests(context.Context, *ListEmergencyRequestsRequest) (*ListEmergencyRequestsResponse, error)
	CancelEmergencyRequest(context.Context, *CancelEmergencyRequestRequest) (*EmergencyRequest, error)
	// ── Operator side ──────────────────────────────────────────────────────────────────
	// Writing the directory. Reached through the gateway's admin routes only.
	CreateProvider(context.Context, *CreateProviderRequest) (*Provider, error)
	UpdateProvider(context.Context, *UpdateProviderRequest) (*Provider, error)
	DeleteProvider(context.Context, *DeleteProviderRequest) (*DeleteResponse, error)
	UpsertProviderService(context.Context, *UpsertProviderServiceRequest) (*ProviderService, error)
	DeleteProviderService(context.Context, *DeleteProviderServiceRequest) (*DeleteResponse, error)
	UpsertPromo(context.Context, *UpsertPromoRequest) (*Promo, error)
	DeletePromo(context.Context, *DeletePromoRequest) (*DeleteResponse, error)
	UpsertFuelStation(context.Context, *UpsertFuelStationRequest) (*FuelStation, error)
	UpsertCity(context.Context, *UpsertCityRequest) (*City, error)
	UpsertCategory(context.Context, *UpsertCategoryRequest) (*Category, error)
	// SeedDemoData fills an empty directory with the demo set the mobile app is designed
	// against. Idempotent, and everything it writes is marked demo so PurgeDemoData can take
	// it all away again — staging is a place to look at the app, not a place to keep rubbish.
	SeedDemoData(context.Context, *SeedDemoDataRequest) (*SeedDemoDataResponse, error)
	PurgeDemoData(context.Context, *PurgeDemoDataRequest) (*PurgeDemoDataResponse, error)
	mustEmbedUnimplementedB2CServiceServer()
}

